// Work MVP Firestore 데이터 저장소
import { 
  collection, 
  doc, 
  setDoc, 
  getDoc, 
  getDocs, 
  deleteDoc,
  query,
  where,
  writeBatch
} from 'firebase/firestore';
import { db, auth } from '../lib/firebase';
import type { Project, ProjectTask, ProjectTodo, Snapshot } from '../types/work';

// ===== 헬퍼 함수 =====

// 현재 사용자 ID 가져오기
function getUserId(): string {
  const user = auth.currentUser;
  if (!user) throw new Error('User not authenticated');
  return user.uid;
}

// 컬렉션 경로 헬퍼
function userCollection(collectionName: string) {
  return collection(db, 'users', getUserId(), collectionName);
}

function userDoc(collectionName: string, docId: string) {
  return doc(db, 'users', getUserId(), collectionName, docId);
}

// ID 생성
export function generateId(prefix: string = ''): string {
  const id = `${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  return prefix ? `${prefix}_${id}` : id;
}

// ===== Projects =====

export async function getProjects(): Promise<Project[]> {
  const snapshot = await getDocs(userCollection('projects'));
  return snapshot.docs.map(doc => doc.data() as Project);
}

export async function getActiveProjects(): Promise<Project[]> {
  // 인덱스 없이 작동하도록 클라이언트 측에서 필터링 및 정렬
  const allProjects = await getProjects();
  return allProjects
    .filter(p => p.status === 'ACTIVE')
    .sort((a, b) => a.priority_order_index - b.priority_order_index);
}

export async function getArchivedProjects(): Promise<Project[]> {
  // 인덱스 없이 작동하도록 클라이언트 측에서 필터링 및 정렬
  const allProjects = await getProjects();
  return allProjects
    .filter(p => p.status === 'ARCHIVED')
    .sort((a, b) => (b.archived_at || 0) - (a.archived_at || 0));
}

export async function getProject(projectId: string): Promise<Project | null> {
  const docRef = userDoc('projects', projectId);
  const docSnap = await getDoc(docRef);
  return docSnap.exists() ? (docSnap.data() as Project) : null;
}

export async function saveProject(project: Project): Promise<void> {
  await setDoc(userDoc('projects', project.id), project);
}

export async function deleteProject(projectId: string): Promise<void> {
  await deleteDoc(userDoc('projects', projectId));
}

// 프로젝트 아카이브 (하위 Task/Todo는 유지)
export async function archiveProject(projectId: string): Promise<void> {
  const project = await getProject(projectId);
  if (project) {
    await saveProject({
      ...project,
      status: 'ARCHIVED',
      archived_at: Date.now(),
      updated_at: Date.now(),
    });
  }
}

// 프로젝트 영구 삭제 (하위 Task/Todo도 모두 삭제)
export async function deleteProjectForever(projectId: string): Promise<void> {
  const batch = writeBatch(db);
  
  // 프로젝트 삭제
  batch.delete(userDoc('projects', projectId));
  
  // 하위 태스크 삭제
  const tasks = await getTasksByProject(projectId);
  for (const task of tasks) {
    batch.delete(userDoc('projectTasks', task.id));
    
    // 태스크 하위 투두 삭제
    const todos = await getTodosByTask(task.id);
    for (const todo of todos) {
      batch.delete(userDoc('projectTodos', todo.id));
    }
  }
  
  await batch.commit();
}

// 프로젝트 우선순위 재정렬
export async function reorderProjects(projectIds: string[]): Promise<void> {
  const batch = writeBatch(db);
  
  projectIds.forEach((id, index) => {
    const docRef = userDoc('projects', id);
    batch.update(docRef, { 
      priority_order_index: (index + 1) * 1000,
      updated_at: Date.now()
    });
  });
  
  await batch.commit();
}

// 새 프로젝트의 우선순위 인덱스 계산 (맨 위에 생성)
export async function getNextProjectPriorityIndex(): Promise<number> {
  const projects = await getActiveProjects();
  if (projects.length === 0) return 1000;
  
  const minIndex = Math.min(...projects.map(p => p.priority_order_index));
  return minIndex - 1000;
}

// ===== Tasks =====

export async function getTasks(): Promise<ProjectTask[]> {
  const snapshot = await getDocs(userCollection('projectTasks'));
  return snapshot.docs.map(doc => doc.data() as ProjectTask);
}

export async function getActiveTasks(): Promise<ProjectTask[]> {
  // 인덱스 없이 작동하도록 클라이언트 측에서 필터링 및 정렬
  const allTasks = await getTasks();
  return allTasks
    .filter(t => t.status === 'ACTIVE')
    .sort((a, b) => a.priority_order_index - b.priority_order_index);
}

export async function getDoneTasks(): Promise<ProjectTask[]> {
  // 인덱스 없이 작동하도록 클라이언트 측에서 필터링 및 정렬
  const allTasks = await getTasks();
  return allTasks
    .filter(t => t.status === 'DONE')
    .sort((a, b) => (b.completed_at || 0) - (a.completed_at || 0));
}

export async function getTasksByProject(projectId: string): Promise<ProjectTask[]> {
  // 인덱스 없이 작동하도록 클라이언트 측에서 필터링 및 정렬
  const allTasks = await getTasks();
  return allTasks
    .filter(t => t.projectId === projectId)
    .sort((a, b) => a.priority_order_index - b.priority_order_index);
}

export async function getTask(taskId: string): Promise<ProjectTask | null> {
  const docRef = userDoc('projectTasks', taskId);
  const docSnap = await getDoc(docRef);
  return docSnap.exists() ? (docSnap.data() as ProjectTask) : null;
}

export async function saveTask(task: ProjectTask): Promise<void> {
  await setDoc(userDoc('projectTasks', task.id), task);
}

export async function deleteTask(taskId: string): Promise<void> {
  const batch = writeBatch(db);
  
  // 태스크 삭제
  batch.delete(userDoc('projectTasks', taskId));
  
  // 하위 투두 삭제
  const todos = await getTodosByTask(taskId);
  for (const todo of todos) {
    batch.delete(userDoc('projectTodos', todo.id));
  }
  
  await batch.commit();
}

// 태스크 완료 처리
export async function completeTask(taskId: string): Promise<void> {
  const task = await getTask(taskId);
  if (task) {
    await saveTask({
      ...task,
      status: 'DONE',
      completed_at: Date.now(),
      updated_at: Date.now(),
    });
  }
}

// 태스크 완료 취소
export async function undoCompleteTask(taskId: string): Promise<void> {
  const task = await getTask(taskId);
  if (task) {
    await saveTask({
      ...task,
      status: 'ACTIVE',
      completed_at: null,
      updated_at: Date.now(),
    });
  }
}

// 태스크 우선순위 재정렬
export async function reorderTasks(taskIds: string[]): Promise<void> {
  const batch = writeBatch(db);
  
  taskIds.forEach((id, index) => {
    const docRef = userDoc('projectTasks', id);
    batch.update(docRef, { 
      priority_order_index: (index + 1) * 1000,
      updated_at: Date.now()
    });
  });
  
  await batch.commit();
}

// 새 태스크의 우선순위 인덱스 계산 (맨 위에 생성)
export async function getNextTaskPriorityIndex(): Promise<number> {
  const tasks = await getActiveTasks();
  if (tasks.length === 0) return 1000;
  
  const minIndex = Math.min(...tasks.map(t => t.priority_order_index));
  return minIndex - 1000;
}

// ===== Todos =====

export async function getProjectTodos(): Promise<ProjectTodo[]> {
  const snapshot = await getDocs(userCollection('projectTodos'));
  return snapshot.docs.map(doc => doc.data() as ProjectTodo);
}

export async function getActiveTodos(): Promise<ProjectTodo[]> {
  // 인덱스 없이 작동하도록 클라이언트 측에서 필터링 및 정렬
  const allTodos = await getProjectTodos();
  return allTodos
    .filter(t => !t.is_done)
    .sort((a, b) => a.priority_order_index - b.priority_order_index);
}

export async function getDoneTodos(): Promise<ProjectTodo[]> {
  // 인덱스 없이 작동하도록 클라이언트 측에서 필터링 및 정렬
  const allTodos = await getProjectTodos();
  return allTodos
    .filter(t => t.is_done)
    .sort((a, b) => (b.completed_at || 0) - (a.completed_at || 0));
}

export async function getTodosByTask(taskId: string): Promise<ProjectTodo[]> {
  // 인덱스 없이 작동하도록 클라이언트 측에서 필터링 및 정렬
  const allTodos = await getProjectTodos();
  return allTodos
    .filter(t => t.taskId === taskId)
    .sort((a, b) => a.priority_order_index - b.priority_order_index);
}

export async function getProjectTodo(todoId: string): Promise<ProjectTodo | null> {
  const docRef = userDoc('projectTodos', todoId);
  const docSnap = await getDoc(docRef);
  return docSnap.exists() ? (docSnap.data() as ProjectTodo) : null;
}

export async function saveProjectTodo(todo: ProjectTodo): Promise<void> {
  await setDoc(userDoc('projectTodos', todo.id), todo);
}

export async function deleteProjectTodo(todoId: string): Promise<void> {
  await deleteDoc(userDoc('projectTodos', todoId));
}

// 투두 완료 처리
export async function completeProjectTodo(todoId: string): Promise<void> {
  const todo = await getProjectTodo(todoId);
  if (todo) {
    await saveProjectTodo({
      ...todo,
      is_done: true,
      completed_at: Date.now(),
      updated_at: Date.now(),
    });
  }
}

// 투두 완료 취소
export async function undoCompleteProjectTodo(todoId: string): Promise<void> {
  const todo = await getProjectTodo(todoId);
  if (todo) {
    await saveProjectTodo({
      ...todo,
      is_done: false,
      completed_at: null,
      updated_at: Date.now(),
    });
  }
}

// 투두 우선순위 재정렬
export async function reorderTodos(todoIds: string[]): Promise<void> {
  const batch = writeBatch(db);
  
  todoIds.forEach((id, index) => {
    const docRef = userDoc('projectTodos', id);
    batch.update(docRef, { 
      priority_order_index: (index + 1) * 1000,
      updated_at: Date.now()
    });
  });
  
  await batch.commit();
}

// 새 투두의 우선순위 인덱스 계산 (맨 위에 생성)
export async function getNextTodoPriorityIndex(taskId: string | null): Promise<number> {
  let todos: ProjectTodo[];
  if (taskId) {
    todos = await getTodosByTask(taskId);
  } else {
    todos = await getActiveTodos();
  }
  
  if (todos.length === 0) return 1000;
  
  const minIndex = Math.min(...todos.map(t => t.priority_order_index));
  return minIndex - 1000;
}

// ===== Snapshots =====

// 스냅샷은 루트 레벨 컬렉션에 저장 (공개 접근용)
function snapshotDoc(snapshotId: string) {
  return doc(db, 'snapshots', snapshotId);
}

export async function getSnapshot(snapshotId: string): Promise<Snapshot | null> {
  const docSnap = await getDoc(snapshotDoc(snapshotId));
  return docSnap.exists() ? (docSnap.data() as Snapshot) : null;
}

export async function getSnapshotByToken(token: string): Promise<Snapshot | null> {
  const q = query(collection(db, 'snapshots'), where('token', '==', token));
  const snapshot = await getDocs(q);
  if (snapshot.empty) return null;
  return snapshot.docs[0].data() as Snapshot;
}

export async function saveSnapshot(snapshot: Snapshot): Promise<void> {
  await setDoc(snapshotDoc(snapshot.id), snapshot);
}

export async function deleteSnapshot(snapshotId: string): Promise<void> {
  await deleteDoc(snapshotDoc(snapshotId));
}

// 프로젝트 스냅샷 생성
export async function createProjectSnapshot(
  projectId: string, 
  options: { includeCompleted: boolean } = { includeCompleted: false }
): Promise<Snapshot> {
  const project = await getProject(projectId);
  if (!project) throw new Error('Project not found');
  
  // 프로젝트의 태스크들 가져오기
  let tasks = await getTasksByProject(projectId);
  if (!options.includeCompleted) {
    tasks = tasks.filter(t => t.status === 'ACTIVE');
  }
  
  // 각 태스크의 투두들 가져오기
  const allTodos: ProjectTodo[] = [];
  for (const task of tasks) {
    let todos = await getTodosByTask(task.id);
    if (!options.includeCompleted) {
      todos = todos.filter(t => !t.is_done);
    }
    allTodos.push(...todos);
  }
  
  // 토큰 생성
  const token = generateId('share');
  
  const snapshot: Snapshot = {
    id: generateId('snap'),
    token,
    ownerId: getUserId(),
    projectId,
    project,
    tasks,
    todos: allTodos,
    options,
    created_at: Date.now(),
    expires_at: null, // 무기한
  };
  
  await saveSnapshot(snapshot);
  return snapshot;
}
