import { useState, useEffect, lazy, Suspense, useCallback } from 'react';
import { HashRouter, Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './contexts/AuthContext';
import { ToastProvider } from './components/Toast';
import ErrorBoundary from './components/ErrorBoundary';
import NetworkStatus from './components/NetworkStatus';
import DemoBanner from './components/DemoBanner';
import SearchModal from './components/SearchModal';
import LoginPage from './pages/LoginPage';
import { getTodayString } from './utils/date';
import { useGlobalShortcuts } from './hooks/useGlobalShortcuts';
import './components/ErrorBoundary.css';

// Lazy loading으로 페이지 분할 (초기 로드 시간 단축)
const DailyPage = lazy(() => import('./pages/DailyPage'));
const MonthlyPage = lazy(() => import('./pages/MonthlyPage'));
const WorkPage = lazy(() => import('./pages/WorkPage'));
const SharePage = lazy(() => import('./pages/SharePage'));

// 로딩 폴백 컴포넌트
function PageLoader() {
  return (
    <div className="loading-screen">
      <div className="loading-spinner">로딩 중...</div>
    </div>
  );
}

const SECRET_CODE = import.meta.env.VITE_SECRET_CODE;

// 비밀 코드 검증 게이트
function SecretGate({ children }: { children: React.ReactNode }) {
  const [isVerified, setIsVerified] = useState(false);
  const [code, setCode] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    // localStorage에서 검증 상태 확인
    const verified = localStorage.getItem('myschedul_verified');
    if (verified === SECRET_CODE) {
      setIsVerified(true);
    }
  }, []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (code === SECRET_CODE) {
      localStorage.setItem('myschedul_verified', SECRET_CODE);
      setIsVerified(true);
      setError('');
    } else {
      setError('Wrong answer. Think again.');
    }
  };

  if (!isVerified) {
    return (
      <div className="gate-page">
        <div className="gate-container">
          <h1>MySchedul</h1>
          <p className="gate-question">ask who made this</p>
          <form onSubmit={handleSubmit}>
            <input
              type="password"
              value={code}
              onChange={(e) => setCode(e.target.value)}
              placeholder="Enter the answer..."
              className="gate-input"
              autoFocus
            />
            <button type="submit" className="gate-btn">Verify</button>
          </form>
          {error && <p className="gate-error">{error}</p>}
        </div>
      </div>
    );
  }

  return <>{children}</>;
}

// 인증 필요한 라우트를 감싸는 컴포넌트
function ProtectedRoutes() {
  const { user, loading } = useAuth();
  const navigate = useNavigate();
  const [isSearchOpen, setIsSearchOpen] = useState(false);

  // 전역 단축키 설정
  useGlobalShortcuts({
    onSearch: useCallback(() => setIsSearchOpen(true), []),
    onToday: useCallback(() => navigate(`/daily/${getTodayString()}`), [navigate]),
  });

  // 검색 이벤트 리스너 (하위 컴포넌트에서 발생)
  useEffect(() => {
    const handleOpenSearch = () => setIsSearchOpen(true);
    window.addEventListener('open-search', handleOpenSearch);
    return () => window.removeEventListener('open-search', handleOpenSearch);
  }, []);

  if (loading) {
    return (
      <div className="loading-screen">
        <div className="loading-spinner">로딩 중...</div>
      </div>
    );
  }

  if (!user) {
    return <LoginPage />;
  }

  return (
    <>
      <SearchModal isOpen={isSearchOpen} onClose={() => setIsSearchOpen(false)} />
      <Suspense fallback={<PageLoader />}>
        <Routes>
          <Route path="/" element={<Navigate to={`/daily/${getTodayString()}`} replace />} />
          <Route path="/daily/:date" element={<DailyPage />} />
          <Route path="/monthly/:month" element={<MonthlyPage />} />
          <Route path="/work" element={<WorkPage />} />
          <Route path="*" element={<Navigate to={`/daily/${getTodayString()}`} replace />} />
        </Routes>
      </Suspense>
    </>
  );
}

function App() {
  return (
    <ErrorBoundary>
      <ToastProvider>
        <NetworkStatus />
        <SecretGate>
          <AuthProvider>
            <DemoBanner />
            <HashRouter>
              <Suspense fallback={<PageLoader />}>
                <Routes>
                  {/* 공유 페이지는 인증 없이 접근 가능 */}
                  <Route path="/share/:token" element={<SharePage />} />
                  {/* 나머지는 인증 필요 */}
                  <Route path="/*" element={<ProtectedRoutes />} />
                </Routes>
              </Suspense>
            </HashRouter>
          </AuthProvider>
        </SecretGate>
      </ToastProvider>
    </ErrorBoundary>
  );
}

export default App;
