// 데모 모드 여부 확인
export function isDemoMode(): boolean {
  return localStorage.getItem('myschedul_demo_mode') === 'true';
}

// 데모 모드 설정
export function setDemoMode(enabled: boolean): void {
  if (enabled) {
    localStorage.setItem('myschedul_demo_mode', 'true');
  } else {
    localStorage.removeItem('myschedul_demo_mode');
  }
}
