// 날짜 관련 유틸리티 함수
import { format, parse, addDays, subDays, startOfMonth, endOfMonth, startOfWeek, endOfWeek, eachDayOfInterval, getDay, getISOWeek, startOfYear, addWeeks } from 'date-fns';
import { ko } from 'date-fns/locale';

// 날짜 포맷
export function formatDate(date: Date): string {
  return format(date, 'yyyy-MM-dd');
}

export function formatDisplayDate(date: Date): string {
  return format(date, 'yyyy-MM-dd (EEE)', { locale: ko });
}

export function formatMonthYear(date: Date): string {
  return format(date, 'yyyy년 M월', { locale: ko });
}

// 날짜 파싱
export function parseDate(dateStr: string): Date {
  return parse(dateStr, 'yyyy-MM-dd', new Date());
}

// 시간 관련
export function parseTime(timeStr: string): { hours: number; minutes: number } {
  const [hours, minutes] = timeStr.split(':').map(Number);
  return { hours, minutes };
}

export function formatTime(hours: number, minutes: number): string {
  return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;
}

// 5분 단위로 스냅
export function snapToStep(minutes: number, step: number = 5): number {
  return Math.round(minutes / step) * step;
}

// 시간을 분으로 변환
export function timeToMinutes(timeStr: string): number {
  const { hours, minutes } = parseTime(timeStr);
  return hours * 60 + minutes;
}

// 분을 시간으로 변환
export function minutesToTime(totalMinutes: number): string {
  const hours = Math.floor(totalMinutes / 60) % 24;
  const minutes = totalMinutes % 60;
  return formatTime(hours, minutes);
}

// 날짜 이동
export function getNextDay(date: Date): Date {
  return addDays(date, 1);
}

export function getPrevDay(date: Date): Date {
  return subDays(date, 1);
}

// 월간 달력용: 해당 월의 모든 날짜
export function getMonthDays(year: number, month: number): Date[] {
  const start = startOfMonth(new Date(year, month - 1));
  const end = endOfMonth(new Date(year, month - 1));
  return eachDayOfInterval({ start, end });
}

// 요일 (0 = 일요일)
export function getDayOfWeek(date: Date): number {
  return getDay(date);
}

// 오늘 날짜
export function getToday(): Date {
  return new Date();
}

export function getTodayString(): string {
  return formatDate(getToday());
}

// 타임라인 시간 배열 생성 (04:00 ~ 03:00, 24시간)
export function getTimelineHours(): number[] {
  const hours: number[] = [];
  // 04:00 ~ 23:00
  for (let h = 4; h <= 23; h++) {
    hours.push(h);
  }
  // 00:00 ~ 03:00
  for (let h = 0; h <= 3; h++) {
    hours.push(h);
  }
  return hours;
}

// 주간 뷰: 해당 주의 모든 날짜 (월~일)
export function getWeekDays(date: Date): Date[] {
  const start = startOfWeek(date, { weekStartsOn: 1 }); // 월요일 시작
  const end = endOfWeek(date, { weekStartsOn: 1 });
  return eachDayOfInterval({ start, end });
}

// 주 번호 가져오기
export function getWeekNumber(date: Date): number {
  return getISOWeek(date);
}

// 특정 년도의 특정 주 시작일 가져오기
export function getWeekStartDate(year: number, weekNum: number): Date {
  const firstDayOfYear = startOfYear(new Date(year, 0, 1));
  return addWeeks(startOfWeek(firstDayOfYear, { weekStartsOn: 1 }), weekNum - 1);
}

// 연간 뷰: 해당 년도의 12개월
export function getYearMonths(year: number): { year: number; month: number; days: Date[] }[] {
  const months: { year: number; month: number; days: Date[] }[] = [];
  for (let m = 1; m <= 12; m++) {
    months.push({
      year,
      month: m,
      days: getMonthDays(year, m)
    });
  }
  return months;
}
