// 전역 검색 모달
import { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import * as store from '../stores/firestore';
import * as workStore from '../stores/workFirestore';
import { generateDemoEvents, generateDemoTodos, generateDemoProjects, generateDemoTasks, generateDemoProjectTodos } from '../utils/demoData';
import './SearchModal.css';

interface SearchModalProps {
  isOpen: boolean;
  onClose: () => void;
}

type SearchResultType = 'event' | 'todo' | 'project' | 'task' | 'projectTodo';

interface SearchResult {
  id: string;
  type: SearchResultType;
  title: string;
  subtitle?: string;
  date?: string;
  color?: string;
  path?: string;
}

export default function SearchModal({ isOpen, onClose }: SearchModalProps) {
  const navigate = useNavigate();
  const { isDemo } = useAuth();
  const inputRef = useRef<HTMLInputElement>(null);
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(0);

  // 모달 열릴 때 입력 포커스
  useEffect(() => {
    if (isOpen) {
      setQuery('');
      setResults([]);
      setSelectedIndex(0);
      setTimeout(() => inputRef.current?.focus(), 100);
    }
  }, [isOpen]);

  // ESC로 닫기
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen) {
        onClose();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  // 검색 수행
  const performSearch = useCallback(async (searchQuery: string) => {
    if (!searchQuery.trim()) {
      setResults([]);
      return;
    }

    setIsLoading(true);
    const searchResults: SearchResult[] = [];
    const lowerQuery = searchQuery.toLowerCase();

    try {
      if (isDemo) {
        // 데모 모드: 샘플 데이터에서 검색
        const today = new Date().toISOString().slice(0, 10);
        const demoEvents = generateDemoEvents(today);
        const demoTodos = generateDemoTodos(today);
        const demoProjects = generateDemoProjects();
        const demoTasks = generateDemoTasks();
        const demoPTodos = generateDemoProjectTodos();

        // 일정 검색
        demoEvents.forEach((event) => {
          if (event.title.toLowerCase().includes(lowerQuery)) {
            searchResults.push({
              id: event.id,
              type: 'event',
              title: event.title,
              subtitle: `${event.start} - ${event.end}`,
              date: event.date,
              color: event.color,
              path: `/daily/${event.date}`,
            });
          }
        });

        // 투두 검색
        demoTodos.forEach((todo) => {
          if (todo.title.toLowerCase().includes(lowerQuery)) {
            searchResults.push({
              id: todo.id,
              type: 'todo',
              title: todo.title,
              subtitle: todo.status,
              date: todo.date,
              path: `/daily/${todo.date}`,
            });
          }
        });

        // 프로젝트 검색
        demoProjects.forEach((project) => {
          if (project.title.toLowerCase().includes(lowerQuery)) {
            searchResults.push({
              id: project.id,
              type: 'project',
              title: project.title,
              color: project.color,
              path: '/work',
            });
          }
        });

        // 태스크 검색
        demoTasks.forEach((task) => {
          if (task.title.toLowerCase().includes(lowerQuery)) {
            const project = demoProjects.find((p) => p.id === task.projectId);
            searchResults.push({
              id: task.id,
              type: 'task',
              title: task.title,
              subtitle: project?.title || '프로젝트 미지정',
              color: project?.color,
              path: '/work',
            });
          }
        });

        // 프로젝트 투두 검색
        demoPTodos.forEach((todo) => {
          if (todo.content.toLowerCase().includes(lowerQuery)) {
            const task = demoTasks.find((t) => t.id === todo.taskId);
            searchResults.push({
              id: todo.id,
              type: 'projectTodo',
              title: todo.content,
              subtitle: task?.title || '태스크 미지정',
              path: '/work',
            });
          }
        });
      } else {
        // 실제 데이터에서 검색
        const [events, todos, projects, tasks, projectTodos] = await Promise.all([
          store.getEvents(),
          store.getTodos(),
          workStore.getActiveProjects(),
          workStore.getActiveTasks(),
          workStore.getActiveTodos(),
        ]);

        // 일정 검색
        events.forEach((event) => {
          if (event.title.toLowerCase().includes(lowerQuery)) {
            searchResults.push({
              id: event.id,
              type: 'event',
              title: event.title,
              subtitle: `${event.start} - ${event.end}`,
              date: event.date,
              color: event.color,
              path: `/daily/${event.date}`,
            });
          }
        });

        // 투두 검색
        todos.forEach((todo) => {
          if (todo.title.toLowerCase().includes(lowerQuery)) {
            searchResults.push({
              id: todo.id,
              type: 'todo',
              title: todo.title,
              subtitle: todo.status,
              date: todo.date,
              path: `/daily/${todo.date}`,
            });
          }
        });

        // 프로젝트 검색
        projects.forEach((project) => {
          if (project.title.toLowerCase().includes(lowerQuery)) {
            searchResults.push({
              id: project.id,
              type: 'project',
              title: project.title,
              color: project.color,
              path: '/work',
            });
          }
        });

        // 태스크 검색
        tasks.forEach((task) => {
          if (task.title.toLowerCase().includes(lowerQuery)) {
            const project = projects.find((p) => p.id === task.projectId);
            searchResults.push({
              id: task.id,
              type: 'task',
              title: task.title,
              subtitle: project?.title || '프로젝트 미지정',
              color: project?.color,
              path: '/work',
            });
          }
        });

        // 프로젝트 투두 검색
        projectTodos.forEach((todo) => {
          if (todo.content.toLowerCase().includes(lowerQuery)) {
            const task = tasks.find((t) => t.id === todo.taskId);
            searchResults.push({
              id: todo.id,
              type: 'projectTodo',
              title: todo.content,
              subtitle: task?.title || '태스크 미지정',
              path: '/work',
            });
          }
        });
      }

      setResults(searchResults.slice(0, 20)); // 최대 20개
      setSelectedIndex(0);
    } catch (error) {
      console.error('Search failed:', error);
    } finally {
      setIsLoading(false);
    }
  }, [isDemo]);

  // 디바운스 검색
  useEffect(() => {
    const timer = setTimeout(() => {
      performSearch(query);
    }, 300);
    return () => clearTimeout(timer);
  }, [query, performSearch]);

  // 키보드 네비게이션
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setSelectedIndex((prev) => Math.min(prev + 1, results.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setSelectedIndex((prev) => Math.max(prev - 1, 0));
    } else if (e.key === 'Enter' && results[selectedIndex]) {
      handleResultClick(results[selectedIndex]);
    }
  };

  // 결과 클릭
  const handleResultClick = (result: SearchResult) => {
    if (result.path) {
      navigate(result.path);
    }
    onClose();
  };

  // 타입별 아이콘
  const getTypeIcon = (type: SearchResultType) => {
    switch (type) {
      case 'event': return '📅';
      case 'todo': return '✅';
      case 'project': return '📁';
      case 'task': return '📋';
      case 'projectTodo': return '☑️';
    }
  };

  // 타입별 라벨
  const getTypeLabel = (type: SearchResultType) => {
    switch (type) {
      case 'event': return '일정';
      case 'todo': return '투두';
      case 'project': return '프로젝트';
      case 'task': return '태스크';
      case 'projectTodo': return '할 일';
    }
  };

  // 검색어 하이라이팅
  const highlightMatch = (text: string) => {
    if (!query.trim()) return text;
    const regex = new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
    const parts = text.split(regex);
    return parts.map((part, i) =>
      regex.test(part) ? <mark key={i}>{part}</mark> : part
    );
  };

  if (!isOpen) return null;

  return (
    <div className="search-modal-overlay" onClick={onClose}>
      <div className="search-modal" onClick={(e) => e.stopPropagation()}>
        {/* 검색 입력 */}
        <div className="search-input-wrapper">
          <span className="search-icon">🔍</span>
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="일정, 투두, 프로젝트 검색..."
            className="search-input"
          />
          <kbd className="search-shortcut">ESC</kbd>
        </div>

        {/* 검색 결과 */}
        <div className="search-results">
          {isLoading ? (
            <div className="search-loading">검색 중...</div>
          ) : results.length === 0 ? (
            query.trim() ? (
              <div className="search-empty">검색 결과가 없습니다.</div>
            ) : (
              <div className="search-hint">
                <p>💡 검색어를 입력하세요</p>
                <p className="hint-examples">예: 미팅, 프로젝트 이름, 할 일...</p>
              </div>
            )
          ) : (
            <ul className="search-result-list">
              {results.map((result, index) => (
                <li
                  key={`${result.type}-${result.id}`}
                  className={`search-result-item ${index === selectedIndex ? 'selected' : ''}`}
                  onClick={() => handleResultClick(result)}
                  onMouseEnter={() => setSelectedIndex(index)}
                >
                  <span className="result-icon">{getTypeIcon(result.type)}</span>
                  <div className="result-content">
                    <span className="result-title">{highlightMatch(result.title)}</span>
                    {result.subtitle && (
                      <span className="result-subtitle">{result.subtitle}</span>
                    )}
                  </div>
                  <div className="result-meta">
                    {result.color && (
                      <span className="result-color" style={{ backgroundColor: result.color }} />
                    )}
                    <span className="result-type">{getTypeLabel(result.type)}</span>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </div>

        {/* 푸터 */}
        <div className="search-footer">
          <span><kbd>↑↓</kbd> 이동</span>
          <span><kbd>Enter</kbd> 선택</span>
          <span><kbd>ESC</kbd> 닫기</span>
        </div>
      </div>
    </div>
  );
}
