// ===== Day Summary =====
export async function getDaySummary(date: string): Promise<DaySummary | null> {
  const docRef = userDoc('days', date);
  const docSnap = await getDoc(docRef);
  return docSnap.exists() ? (docSnap.data() as DaySummary) : null;
}

export async function saveDaySummary(summary: DaySummary): Promise<void> {
  await setDoc(userDoc('days', summary.date), summary);
}

// ===== 태그 =====
