// 로그인 페이지
import { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { setDemoMode } from '../utils/demoData';
import '../styles/LoginPage.css';

// 비밀 코드는 환경 변수에서 가져옴
const SECRET_CODE = import.meta.env.VITE_SECRET_CODE;

export default function LoginPage() {
  const { signInWithGoogle } = useAuth();
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [secretCode, setSecretCode] = useState('');
  const [isCodeVerified, setIsCodeVerified] = useState(false);

  // 이전에 인증된 적 있는지 확인 (localStorage)
  useEffect(() => {
    const verified = localStorage.getItem('code_verified');
    if (verified === 'true') {
      setIsCodeVerified(true);
    }
  }, []);

  const handleCodeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (secretCode === SECRET_CODE) {
      setIsCodeVerified(true);
      localStorage.setItem('code_verified', 'true');
      setError(null);
    } else {
      setError('Wrong answer. Think again.');
    }
  };

  const handleGoogleLogin = async () => {
    setIsLoading(true);
    setError(null);
    try {
      await signInWithGoogle();
    } catch (err) {
      setError('로그인에 실패했습니다. 다시 시도해주세요.');
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="login-page">
      <div className="login-container">
        <div className="login-header">
          <h1>MySchedul</h1>
          <p>나만의 일정 관리</p>
        </div>

        <div className="login-content">
          {!isCodeVerified ? (
            // 비밀 코드 입력 단계
            <>
              <p className="login-question">ask who made this</p>
              
              <form onSubmit={handleCodeSubmit} className="code-form">
                <input
                  type="password"
                  value={secretCode}
                  onChange={(e) => setSecretCode(e.target.value)}
                  placeholder="Enter the answer..."
                  className="code-input"
                  autoFocus
                />
                <button type="submit" className="code-submit-btn">
                  Verify
                </button>
              </form>

              {error && (
                <p className="login-error">{error}</p>
              )}
            </>
          ) : (
            // Google 로그인 단계
            <>
              <p className="login-description">
                계속하려면 Google 계정으로 로그인하세요.
                <br />
                <small>한 번 로그인하면 자동으로 유지됩니다.</small>
              </p>

              <button 
                className="google-login-btn"
                onClick={handleGoogleLogin}
                disabled={isLoading}
              >
                {isLoading ? (
                  '로그인 중...'
                ) : (
                  <>
                    <svg viewBox="0 0 24 24" width="20" height="20">
                      <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
                      <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
                      <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/>
                      <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
                    </svg>
                    Google로 로그인
                  </>
                )}
              </button>

              <div className="login-divider">
                <span>또는</span>
              </div>

              <button
                className="demo-mode-btn"
                onClick={() => {
                  setDemoMode(true);
                  window.location.reload();
                }}
              >
                🎮 데모 모드로 체험하기
              </button>
              <p className="demo-hint">
                로그인 없이 샘플 데이터로 앱을 체험해보세요.
              </p>

              {error && (
                <p className="login-error">{error}</p>
              )}
            </>
          )}
        </div>

        <div className="login-footer">
          <p>🔒 데이터는 안전하게 암호화되어 저장됩니다.</p>
        </div>
      </div>
    </div>
  );
}
